#include "Directives.hpp"

#pragma once

/**
 * @class ExampleDirective
 * @brief Example directive demonstrating the directive system
 * 
 * This class serves as a template for creating new directive types.
 * It shows how to:
 * - Use DEFINE_DIRECTIVE macro for registration
 * - Access arguments in constructor
 * - Specify allowed parent contexts
 * 
 * Configuration Example:
 * @code
 *   example arg1 arg2;
 * @endcode
 * 
 * Allowed Contexts:
 * - Inside GlobalDirective (root level only)
 */
class ExampleDirective: public IDirective
{
private:
	
public:
	/**
	 * @brief Default constructor
	 */
	ExampleDirective();
	
	/**
	 * @brief Constructor with arguments
	 * @param args Argument vector (args[0] is "example", args[1+] are user args)
	 */
	ExampleDirective(const std::vector<std::string>& args);
	
	/**
	 * @brief Copy constructor
	 * @param other ExampleDirective to copy from
	 */
	ExampleDirective(const ExampleDirective &other);
	
	/**
	 * @brief Assignment operator
	 * @param other ExampleDirective to assign from
	 * @return Reference to this
	 */
	ExampleDirective &operator=(const ExampleDirective &other);
	
	/**
	 * @brief Destructor
	 */
	~ExampleDirective();
	
	/**
	 * @brief Declares getAllowedInside() method
	 * @note Implementation generated by DEFINE_DIRECTIVE macro
	 */
	DEFINE_ALLOWED_INSIDE();
};
